6	
7	export interface DialogProps {
8	  open: boolean;
9	  onClose: () => void;
10	  title: string;
11	  children: React.ReactNode;
12	  /** Optional footer (e.g. action buttons). */
13	  footer?: React.ReactNode;
14	}
15	
16	/**
17	 * Modal dialog built on the native <dialog> element, which gives us focus
18	 * trapping, Esc-to-close, and inert background for free. Labelled by its title.
19	 */
20	export function Dialog({ open, onClose, title, children, footer }: DialogProps) {
21	  const ref = React.useRef<HTMLDialogElement>(null);
22	  const titleId = React.useId();
23	
24	  React.useEffect(() => {
25	    const dialog = ref.current;
26	    if (!dialog) return;
27	    if (open && !dialog.open) {
28	      // showModal isn't implemented in jsdom; fall back to the open attribute.
29	      try {
30	        dialog.showModal();
31	      } catch {
32	        dialog.open = true;
33	      }
34	    } else if (!open && dialog.open) {
35	      try {
36	        dialog.close();
37	      } catch {
38	        dialog.open = false;
39	      }
40	    }
41	  }, [open]);
42	
43	  return (
44	    <dialog
45	      ref={ref}
46	      aria-labelledby={titleId}
47	      onClose={onClose}
48	      onClick={(e) => {
49	        // Close when the backdrop (the dialog element itself) is clicked.
50	        if (e.target === ref.current) onClose();
51	      }}
52	      className="m-auto w-[min(92vw,32rem)] rounded-lg border border-border bg-surface p-0 text-ink shadow-lg backdrop:bg-ink/40"
53	    >
54	      <div className="flex items-start justify-between gap-4 border-b border-border px-6 pt-5 pb-4">
55	        <h2 id={titleId} className="text-h3">
56	          {title}
57	        </h2>
58	        <button
59	          type="button"
60	          onClick={onClose}
61	          aria-label={t("safety.close")}
62	          className="-m-2 rounded-sm p-2 text-ink-soft hover:text-ink"
63	        >
64	          <X size={22} strokeWidth={2} aria-hidden="true" />
65	        </button>
66	      </div>
67	      <div className="px-6 py-5">{children}</div>
68	      {footer ? (
69	        <div className="flex flex-wrap justify-end gap-3 border-t border-border px-6 py-4">
70	          {footer}
71	        </div>
72	      ) : null}
73	    </dialog>
74	  );
75	}
